from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books = set()                # available book ids
        self._borrowed = {}                # book_id -> (user, due_date)
        self._user_books = {}              # user -> set of book_ids
        self._fines = {}                   # user -> unpaid fine amount

    def add_book(self, book_id: str) -> None:
        if book_id in self._books or book_id in self._borrowed:
            raise ValueError(f"Book {book_id!r} already exists")
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Book {book_id!r} is not available")
        held = self._user_books.get(user, set())
        if self._fines.get(user, 0.0) > 0 and len(held) >= 1:
            raise ValueError(
                f"User {user!r} has unpaid fines and already holds a book"
            )
        due = day + timedelta(days=self.loan_days)
        self._books.discard(book_id)
        self._borrowed[book_id] = (user, due)
        self._user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        record = self._borrowed.get(book_id)
        if record is None or record[0] != user:
            raise ValueError(
                f"User {user!r} has not borrowed book {book_id!r}"
            )
        _, due = record
        fine = 0.0
        if day > due:
            fine = self._count_business_days(due, day) * self.daily_fine
        del self._borrowed[book_id]
        self._books.add(book_id)
        self._user_books[user].discard(book_id)
        if not self._user_books[user]:
            del self._user_books[user]
        if fine > 0:
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)

    @staticmethod
    def _count_business_days(start: date, end: date) -> int:
        """Count weekdays strictly after `start` up to and including `end`."""
        count = 0
        cur = start + timedelta(days=1)
        while cur <= end:
            if cur.weekday() < 5:
                count += 1
            cur += timedelta(days=1)
        return count
